import{readFile,writeFile}from'node:fs/promises';
const path=process.argv[2]??'.tmp/ssr-sustained/full.json';
const raw=JSON.parse(await readFile(path));const rows=[];
for(const p of raw.populations)for(const b of p.blocks)for(const s of b.measured.stages){
 if(s.discard)continue;
 const start=Date.parse(s.startedAt),end=start+s.elapsedMs;
 const points=b.telemetry.filter(t=>t.epochMs>=start&&t.epochMs<=end);
 const first=points[0],last=points.at(-1);const phases={};
 if(first&&last&&first!==last)for(const key of ['totalMs','dataLoadMs','renderMs','envelopeMs']){const a=first.value.statistics[key],z=last.value.statistics[key];phases[key]=(z.sum-a.sum)/(z.count-a.count);}
